  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============================================================\n// MULTI-TENANT : 2 boutiques sur 1 backend\n// ============================================================\n\nmodel Store {\n  id          String   @id @default(cuid())\n  name        String // \"omen-shoes\" | \"omen-wellness\"\n  displayName String // \"oMen Shoes\" | \"oMen Wellness\"\n  domain      String   @unique // \"omenshoes.com\" | \"omenwellness.com\"\n  logoUrl     String?\n  active      Boolean  @default(true)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  products  Product[]\n  orders    Order[]\n  customers Customer[]\n}\n\n// ============================================================\n// PRODUITS\n// ============================================================\n\nmodel Product {\n  id          String   @id @default(cuid())\n  storeId     String\n  store       Store    @relation(fields: [storeId], references: [id])\n  name        String\n  slug        String   @unique\n  description String?\n  price       Int // Prix de base en FCFA\n  compareAt   Int? // Prix barré\n  category    String\n  tags        String   @default(\"\") // Stocké comme \"tag1,tag2,tag3\"\n  active      Boolean  @default(true)\n  featured    Boolean  @default(false)\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  orderItems OrderItem[]\n  colors     ProductColor[]\n  images     ProductImage[]\n  variants   ProductVariant[]\n\n  @@index([storeId, category])\n  @@index([storeId, active])\n}\n\nmodel ProductColor {\n  id        String   @id @default(cuid())\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  name      String // \"Noir\", \"Blanc\", \"Chicago\", etc.\n  hex       String // Code couleur hex #RRGGBB\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  images   ProductImage[]\n  variants ProductVariant[]\n\n  @@unique([productId, name])\n  @@index([productId])\n}\n\nmodel ProductImage {\n  id        String        @id @default(cuid())\n  productId String\n  product   Product       @relation(fields: [productId], references: [id], onDelete: Cascade)\n  colorId   String?\n  color     ProductColor? @relation(fields: [colorId], references: [id], onDelete: SetNull)\n  url       String\n  alt       String?\n  sortOrder Int           @default(0)\n  isMain    Boolean       @default(false)\n  createdAt DateTime      @default(now())\n}\n\nmodel ProductVariant {\n  id        String        @id @default(cuid())\n  productId String\n  product   Product       @relation(fields: [productId], references: [id], onDelete: Cascade)\n  colorId   String?\n  color     ProductColor? @relation(fields: [colorId], references: [id], onDelete: SetNull)\n  size      String // \"38\", \"39\", \"40\", \"S\", \"M\", \"L\", etc.\n  sku       String? // Référence interne optionnelle\n  price     Int? // Prix spécifique à ce variant (null = prix produit)\n  compareAt Int? // Prix barré spécifique\n  stock     Int           @default(0)\n  active    Boolean       @default(true)\n  createdAt DateTime      @default(now())\n  updatedAt DateTime      @updatedAt\n\n  orderItems OrderItem[]\n\n  @@unique([productId, colorId, size])\n  @@index([productId, active])\n  @@index([productId, colorId])\n}\n\n// ============================================================\n// CLIENTS\n// ============================================================\n\nmodel Customer {\n  id        String   @id @default(cuid())\n  storeId   String\n  store     Store    @relation(fields: [storeId], references: [id])\n  email     String\n  phone     String?\n  name      String?\n  address   String? // JSON string: { street, city, country, zip }\n  orders    Order[]\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([storeId, email])\n}\n\n// ============================================================\n// COMMANDES\n// ============================================================\n\nmodel Order {\n  id              String    @id @default(cuid())\n  storeId         String\n  store           Store     @relation(fields: [storeId], references: [id])\n  customerId      String?\n  customer        Customer? @relation(fields: [customerId], references: [id])\n  reference       String    @unique // Référence GeniusPay (MTX-...)\n  status          String    @default(\"PENDING\") // PENDING | PROCESSING | SHIPPED | DELIVERED | CANCELLED | REFUNDED\n  subtotal        Int\n  shipping        Int       @default(0)\n  total           Int\n  currency        String    @default(\"XOF\")\n  paymentMethod   String? // \"wave\", \"orange_money\", \"mtn\", \"card\"\n  paymentRef      String? // GeniusPay reference\n  shippingAddress String? // JSON string snapshot de l'adresse\n  notes           String?\n  createdAt       DateTime  @default(now())\n  updatedAt       DateTime  @updatedAt\n\n  items OrderItem[]\n\n  @@index([storeId, status])\n  @@index([reference])\n}\n\nmodel OrderItem {\n  id        String          @id @default(cuid())\n  orderId   String\n  order     Order           @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product         @relation(fields: [productId], references: [id])\n  variantId String?\n  variant   ProductVariant? @relation(fields: [variantId], references: [id])\n  name      String // Snapshot du nom\n  price     Int // Snapshot du prix\n  quantity  Int\n}\n\n// ============================================================\n// ADMIN USERS (Dashboard)\n// ============================================================\n\nmodel AdminUser {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  password  String // bcrypt hash\n  name      String\n  role      String   @default(\"ADMIN\") // SUPER_ADMIN | ADMIN | EDITOR\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\n// ============================================================\n// PAIEMENTS GeniusPay\n// ============================================================\n\nmodel PaymentLog {\n  id        String   @id @default(cuid())\n  orderId   String\n  reference String // GeniusPay reference (MTX-...)\n  event     String // \"payment.created\", \"payment.success\", \"payment.failed\"\n  payload   String // JSON string webhook payload\n  processed Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  @@index([reference])\n}\n",
